// DejaVu Sans (subset: Latin + Latin Extended-A + €) za jsPDF — podržava š ž ć č đ, ü ö ä ß.
// Registruje font 'DejaVuSans' (normal + bold) da PDF ima ispravna slova na SR/EN/DE.
export const DEJAVU_REG = "";
export const DEJAVU_BOLD = "";

export function registerDejaVu(doc) {
  try {
    doc.addFileToVFS("DejaVuSans.ttf", DEJAVU_REG);
    doc.addFont("DejaVuSans.ttf", "DejaVuSans", "normal");
    doc.addFileToVFS("DejaVuSans-Bold.ttf", DEJAVU_BOLD);
    doc.addFont("DejaVuSans-Bold.ttf", "DejaVuSans", "bold");
    return true;
  } catch (e) { return false; }
}